const fs = require('fs');
const coa = {};
fs.readFileSync('finance/chart_of_accounts.csv','utf8').trim().split(/\r?\n/).slice(1)
  .forEach(l=>{const [acc,name,line]=l.split(';');coa[acc]=line;});
const rows = fs.readFileSync('finance/ledger.csv','utf8').trim().split(/\r?\n/).slice(1);
const num = s => parseFloat(s.replace(/\./g,'').replace(',','.'));
const months = {};
let count=0;
for (const l of rows) {
  const [d,acc,desc,amt]=l.split(';');
  count++;
  const [dd,mm,yyyy]=d.split('/');
  if (yyyy!=='2026') { console.log('OFF-YEAR', l); continue; }
  const k=`${yyyy}-${mm}`;
  if (+mm>6) { console.log('H2 ROW', l); continue; }
  const line=coa[acc];
  if (!line) { console.log('UNKNOWN ACCT', acc, l); continue; }
  months[k] ??= {};
  months[k][line] = (months[k][line]||0) + num(amt);
}
console.log('ledger rows:', count, 'unknown accounts/off-period: see above if any');
const out={revenue:{},gross_margin_pct:{},ebitda:{}};
const m=Object.keys(months).sort();
let table=[];
for (const k of m) {
  const o=months[k];
  const rev=o.revenue||0, cogs=o.cogs||0, opex=(o.sales_marketing||0)+(o.rnd||0)+(o.ga||0);
  const gm=(rev+cogs)/rev*100;
  const ebitda=rev+cogs+opex;
  out.revenue[k]=+rev.toFixed(2);
  out.gross_margin_pct[k]=+gm.toFixed(2);
  out.ebitda[k]=+ebitda.toFixed(2);
  table.push({month:k,revenue:+rev.toFixed(2),cogs:+cogs.toFixed(2),opex:+opex.toFixed(2),gross_margin_pct:+gm.toFixed(2),ebitda:+ebitda.toFixed(2)});
}
console.table(table);
// burn: average monthly negative EBITDA of last three closed months
const last3=m.slice(-3);
console.log('last three closed months:', last3.join(', '));
const negEbitda=last3.map(k=>{const o=months[k];return (o.revenue||0)+(o.cogs||0)+(o.sales_marketing||0)+(o.rnd||0)+(o.ga||0);});
console.log('their EBITDA:', negEbitda.map(x=>x.toFixed(2)).join(', '));
const burn=-(negEbitda.reduce((a,b)=>a+b,0)/3);
const cash=1847350.40; // 30/06/2026 latest closing balance
console.log('burn (avg monthly negative EBITDA):', burn.toFixed(2));
console.log('runway months:', (cash/burn).toFixed(2));
out.burn=+burn.toFixed(2);
out.runway_months=+(cash/burn).toFixed(2);
fs.writeFileSync('result.json', JSON.stringify(out,null,2));
console.log('wrote result.json');
